\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{CJKutf8}

\title{Photochemical Alteration of Chromophoric Dissolved Organic Matter
in Coastal Waters of the Yellow Sea}
\author{L.~Marchetti, Q.~Sun, and E.~Vasquez}
\date{}

\begin{document}
\maketitle

\begin{abstract}
Chromophoric dissolved organic matter controls the underwater light
field and mediates photochemical reactions in coastal seas. We report
incubation experiments that quantify how absorption by this material
decays under simulated sunlight and how its spectral shape shifts during
photobleaching.
\end{abstract}

\section{Introduction}
Absorption of ultraviolet and visible radiation by coloured dissolved
matter limits the depth of the euphotic zone and fuels the production of
reactive intermediates in surface waters.

\begin{CJK}{UTF8}{gbsn}
\section{CDOM 光漂白动力学}
有色溶解有机物（CDOM）强烈吸收紫外与可见光，是控制真光层光场的重要因子。在阳光辐照下，CDOM 发生光漂白，其吸收系数随时间近似指数衰减：
\begin{equation}
a_{\mathrm{CDOM}}(\lambda, t) = a_0(\lambda)\, e^{-k_{\lambda}\, t}
\label{eq:decay}
\end{equation}
其中 $a_0(\lambda)$ 为初始吸收系数，$k_{\lambda}$ 为波长 $\lambda$ 处的光漂白速率常数，相应的半衰期为 $t_{1/2} = \ln 2 / k_{\lambda}$。为刻画光谱形状的变化，定义光谱斜率比：
\begin{equation}
S_R = \frac{S_{275{-}295}}{S_{350{-}400}}
\label{eq:slope}
\end{equation}
由于光漂白优先去除长波段吸收，$S_R$ 随辐照时间单调增大。培养实验中，样品置于氙灯辐照装置内，每 24 小时取样测定吸收光谱。
\end{CJK}

\begin{CJK}{UTF8}{gbsn}
\section{结论}
光漂白显著降低了近岸水体中有色溶解有机物的吸收，并改变其光谱形状；定量参数化这些过程有助于改进生物光学模型。
\end{CJK}

\end{document}
